import re

def extract_passengers(val):
    if pd.isna(val) or not isinstance(val, str):
        return None
    match = re.search(r'Occupants:\s*(\d+)', val)
    if match:
        return int(match.group(1))
    return None

passengers = df['Onboard_Passengers'].apply(extract_passengers).dropna()
result = passengers.nlargest(5).tolist()
